async function findProject() {
  const result = await core.memory.getMemory("brain://briefing");
  return result;
}
return await findProject();

const stats = await mj.analytics.getStatistics({ workspace_id: '*' });
const projectBreakdown = stats.projectBreakdown || stats.statistics?.projectBreakdown;

// Also test direct query per workspace_id vs project_number
const projects = await mj.admin.listProjects({});
const realBreakdown = [];

for (const p of projects) {
  const pName = p.name || p.projectName;
  const pNum = p.project_number || p.projectNumber;
  const pWs = p.workspaceId || pName;

  // Try querying with workspace_id matching the project workspace
  const resWs = await mj.core.getRecentEntries({ limit: 1000, workspace_id: pWs });
  const resNum = await mj.core.getRecentEntries({ limit: 1000, project_number: pNum, workspace_id: '*' });

  realBreakdown.push({
    name: pName,
    projectNumber: pNum,
    workspaceId: pWs,
    countByWorkspaceId: resWs.entries ? resWs.entries.length : 0,
    countByProjectNumberWithStarWs: resNum.entries ? resNum.entries.length : 0
  });
}

return {
  statsProjectBreakdown: projectBreakdown,
  realBreakdown
};
